revoke all on function api.client_skip_consume_inbound(uuid,uuid),api.client_skip_list(uuid,jsonb),api.client_skip_get(uuid,uuid),api.client_skip_rematch(uuid,uuid,uuid,date,integer,text,uuid),api.client_skip_approve(uuid,uuid,integer,text,uuid),api.client_skip_reject(uuid,uuid,integer,text,text,uuid),api.client_skip_route_impact(uuid,uuid),api.client_skip_replan(uuid,uuid,text,uuid),api.client_skip_history(uuid,uuid)from public,anon,authenticated;
grant execute on function api.client_skip_consume_inbound(uuid,uuid),api.client_skip_list(uuid,jsonb),api.client_skip_get(uuid,uuid),api.client_skip_rematch(uuid,uuid,uuid,date,integer,text,uuid),api.client_skip_approve(uuid,uuid,integer,text,uuid),api.client_skip_reject(uuid,uuid,integer,text,text,uuid),api.client_skip_route_impact(uuid,uuid),api.client_skip_replan(uuid,uuid,text,uuid),api.client_skip_history(uuid,uuid)to service_role;
